  "{tabs} tabs · {tools} tools · {sections} sections · {styles} styles · {plans} plans": ["{tabs} onglets · {tools} outils · {sections} sections · {styles} styles · {plans} forfaits", "{tabs} تبويبات · {tools} أدوات · {sections} أقسام · {styles} أنماط · {plans} باقات", "{tabs} تابات · {tools} أدوات · {sections} أقسام · {styles} ستايلات · {plans} باقات"],
